    'channels.hint.feishu.permission2': 'หากแพลตฟอร์มแจ้งว่า scope ไม่พอ ให้เพิ่มสิทธิ์และเผยแพร่แอปใหม่ก่อนลองอีกครั้ง',
    'channels.hint.feishu.ssl1': 'ถ้าเครือข่ายผ่าน enterprise proxy หรือ HTTPS inspection ให้ตรวจว่าใบรับรอง proxy เชื่อถือได้',
