    'channels.hint.sharecrm.missing2': 'แนะนำให้เทียบฟิลด์กับหน้าคอนฟิก robot ใน ShareCRM IM Gateway ทีละรายการ',
    'channels.hint.sharecrm.credential1': 'ตรวจใน ShareCRM IM Gateway หรือ open platform ว่า App ID และ App Secret ของ bot ยังเปิดใช้งานและไม่หมดอายุ',
    'channels.hint.sharecrm.credential2': 'ยืนยันว่า bot account มีสิทธิ์พอสำหรับ token, รับบทสนทนา และส่งข้อความ',
    'channels.hint.sharecrm.generic1': 'ถ้าเป็น gateway, 404 หรือ 5xx ให้ตรวจ Gateway Base URL ก่อนว่าชี้ environment ถูกต้อง',
    'channels.hint.wecom.missing1': 'อย่างน้อยต้องกรอก Bot ID และ Secret และถ้าใช้ WeCom AI Bot WebSocket gateway ให้ตรวจ WebSocket URL ด้วย',
    'channels.hint.wecom.missing2': 'ถ้าบอทเพิ่งสร้างใหม่ ให้แน่ใจว่าเผยแพร่และพร้อมใช้งานในหลังบ้าน WeCom แล้ว',
    'channels.hint.wecom.credential1': 'ตรวจใน WeCom AI Bot console ว่า Bot ID และ Secret มาจากบอทตัวเดียวกันและมีสิทธิ์รับ/ส่งข้อความ',
    'channels.hint.wecom.credential2': 'ถ้าเชื่อมต่อแล้วถูกปิดทันที ให้สงสัย secret, permission และสถานะบอทก่อนเครือข่าย local',
